package template

import (
	"path/filepath"
	"sync"
	"text/template"

	"github.com/Masterminds/sprig/v3"
)

// dangerousFuncs execute host commands or touch the filesystem/environment
// directly. They are only exposed to templates rendered via RenderTrusted
// (see text.go) — never to RenderUntrusted, which may contain or be composed
// from runtime data.
var dangerousFuncs = map[string]bool{
	"cmd":       true,
	"readFile":  true,
	"stat":      true,
	"glob":      true,
	"env":       true,
	"expandenv": true,
}

func baseFuncMap() map[string]any {
	fm := map[string]any{
		"secondsRound": secondsRound,
		"url":          url,
		"path":         filePath,
		"matchP":       matchP,
		"findP":        findP,
		"replaceP":     replaceP,
		"gt":           gt,
		"lt":           lt,
		"random":       random,
		"reason":       GetReasonFromStatus,
		"hresult":      hresult,
		"trunc":        trunc,
		"truncE":       TruncE,
		"dir":          filepath.Dir,
		"base":         filepath.Base,
		// Locale-aware date/time formatting using OS regional settings.
		"localeShortDate": localeShortDate,
		"localeShortTime": localeShortTime,
		// Override sprig date functions to support string epoch values (e.g. output of unixEpoch).
		"date":           ompDate,
		"date_in_zone":   ompDateInZone,
		"dateInZone":     ompDateInZone,
		"htmlDate":       ompHTMLDate,
		"htmlDateInZone": ompHTMLDateInZone,
	}

	for key, fun := range sprig.TxtFuncMap() {
		if dangerousFuncs[key] {
			continue
		}

		if _, ok := fm[key]; !ok {
			fm[key] = fun
		}
	}

	return fm
}

var sharedFuncMap = sync.OnceValue(func() template.FuncMap {
	fm := baseFuncMap()

	fm["cmd"] = cmd
	fm["readFile"] = readFile
	fm["stat"] = stat
	fm["glob"] = glob

	sprigFuncs := sprig.TxtFuncMap()
	if fn, ok := sprigFuncs["env"]; ok {
		fm["env"] = fn
	}

	if fn, ok := sprigFuncs["expandenv"]; ok {
		fm["expandenv"] = fn
	}

	return template.FuncMap(fm)
})

// Reused across all restricted template constructions (see RenderRestricted);
// never contains dangerousFuncs.
var restrictedFuncMap = sync.OnceValue(func() template.FuncMap {
	return template.FuncMap(baseFuncMap())
})

func funcMap(trusted bool) template.FuncMap {
	if trusted {
		return sharedFuncMap()
	}

	return restrictedFuncMap()
}

package template

import (
	"bytes"
	"errors"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"text/template"
	"unicode"
	"unicode/utf8"

	"github.com/jandedobbeleer/oh-my-posh/src/cache"
	"github.com/jandedobbeleer/oh-my-posh/src/generics"
	"github.com/jandedobbeleer/oh-my-posh/src/log"
)

type Data any

type context struct {
	Data
	Getenv func(string) string
	cache.Template
}

func (c *context) init(t *Text) {
	c.Data = t.context
	c.Getenv = env.Getenv
	c.Template = *Cache
}

var (
	renderPool *generics.Pool[*renderer]
)

// renderer holds only per-render mutable state: an output buffer and a context.
// The parsed template is now looked up from the shared parsedTemplates cache.
type renderer struct {
	context *context
	buffer  bytes.Buffer
}

func (t *renderer) release() {
	t.buffer.Reset()
	t.context.Data = nil
	renderPool.Put(t)
}

// Encodes the raw (unpatched) template text, the trust level (parsed
// templates are bound to a func map at Parse time, so a trusted and a
// restricted render of identical text must never share a cache entry), and,
// when context is non-nil, the reflect.Type of the context so that two
// different struct types whose patchTemplate output would differ (via
// hasField) get separate cache entries. For map[string]any contexts the key
// also includes the sorted exported key names, since patchTemplate output
// depends on which keys are present.
func templateCacheKey(rawText string, trusted bool, ctx any) string {
	key := rawText + "\x00" + strconv.FormatBool(trusted)

	if ctx == nil {
		return key
	}

	t := reflect.TypeOf(ctx)
	if t.Kind() == reflect.Map {
		if m, ok := ctx.(map[string]any); ok {
			keys := make([]string, 0, len(m))
			for k := range m {
				if r, _ := utf8.DecodeRuneInString(k); unicode.IsUpper(r) {
					keys = append(keys, k)
				}
			}
			sort.Strings(keys)
			return key + "\x00" + t.String() + "\x00" + strings.Join(keys, "\x01")
		}
	}

	return key + "\x00" + t.String()
}

// The first call for a given key parses and stores it; subsequent calls
// return the cached value. Concurrent first-renders of the same template
// may both parse, but LoadOrStore ensures only one result is shared.
func parsedTemplate(text *Text) (*template.Template, error) {
	// Key on the raw, unpatched template text plus the trust level and context
	// type so that cache hits can skip patchTemplate entirely: patching is only
	// needed the first time a given (raw template, trust level, context type)
	// combination is seen.
	key := templateCacheKey(text.template, text.trusted, text.context)

	if cached, ok := parsedTemplates.Load(key); ok {
		return cached.(*template.Template), nil
	}

	// Cache miss: patch the raw template into its executable form.
	text.patchTemplate()

	// Parse into a fresh template with the func map matching this render's trust level.
	tmpl, err := template.New("cache").Funcs(funcMap(text.trusted)).Parse(text.template)
	if err != nil {
		return nil, err
	}

	// Store; if another goroutine already stored an equivalent template, use theirs.
	actual, _ := parsedTemplates.LoadOrStore(key, tmpl)
	return actual.(*template.Template), nil
}

func (t *renderer) execute(text *Text) (string, error) {
	tmpl, err := parsedTemplate(text)
	if err != nil {
		log.Error(err)
		return "", errors.New(InvalidTemplate)
	}

	t.context.init(text)

	err = tmpl.Execute(&t.buffer, t.context)
	if err != nil {
		log.Error(err)
		return "", errors.New(IncorrectTemplate)
	}

	output := t.buffer.String()

	// issue with missingkey=zero ignored for map[string]any
	// https://github.com/golang/go/issues/24963
	output = strings.ReplaceAll(output, "<no value>", "")

	return output, nil
}

